#include <stdio.h>
#include <queue>
#include <cctype>
#include <vector>
#include <cstring>
using namespace std;

const int BIG = 12345678;

struct Coord {
    int row, col, tag;
};

struct Storage {
    int list[1000];
    int size;
    int on;
};

Storage store[100][100];
vector<int> edges[1000];
int N, T;
int matchL[1000], matchR[1000], mark[1000];
char maze1[1000][1000], maze2[1000][1000];
int dist1[1000][1000], dist2[1000][1000];
queue<Coord> que;

void BFS_A(Coord s);
void BFS_B(Coord s);
int hopcroft(int total);
bool augment(int u);

int main() {
    int i, j, k, l;
    Coord cur, nxt;

    scanf("%d %d", &N, &T);

    for (i = 0; i <= N; i++)
        for (j = 0; j <= N; j++)
            dist1[i][j] = BIG;

    for (i = 0; i < N; i++) scanf("%s", maze1[i]);
    for (i = 0; i < N; i++) scanf("%s", maze2[i]);

    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            if (maze1[i][j] == 'Z') {
                cur.row = i; cur.col = j;
                BFS_A(cur);
            }

    int counter = 1;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            if (isdigit(maze2[i][j])) {
                k = maze2[i][j] - '0';
                if (k > 0) store[i][j].on = 1;
                store[i][j].size = k;
                for (l = 1; l <= k; l++)
                    store[i][j].list[l] = counter++;
            }

    counter = 1;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            if (isdigit(maze1[i][j])) {
                k = maze1[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    cur.row = i; cur.col = j; cur.tag = counter++;
                    BFS_B(cur);
                }
            }

    printf("%d\n", hopcroft(counter - 1));
    return 0;
}

bool augment(int u) {
    if (mark[u]) return false;
    mark[u] = 1;
    for (int i = 0; i < (int)edges[u].size(); i++) {
        int v = edges[u][i];
        if (matchL[v] == -1) {
            matchL[v] = u;
            matchR[u] = i;
            return true;
        } else if (augment(matchL[v])) {
            matchL[v] = u;
            matchR[u] = i;
            return true;
        }
    }
    return false;
}

int hopcroft(int total) {
    memset(matchL, -1, sizeof(matchL));
    memset(matchR, -1, sizeof(matchR));
    bool changed;
    while (true) {
        changed = false;
        memset(mark, 0, sizeof(mark));
        for (int i = 1; i <= total; i++)
            if (matchR[i] == -1 && augment(i))
                changed = true;
        if (!changed) break;
    }
    int ans = 0;
    for (int i = 1; i <= total; i++)
        if (matchR[i] != -1) ans++;
    return ans;
}

void BFS_B(Coord s) {
    int i, j, k, l;
    Coord cur, nxt;
    for (i = 0; i <= N; i++)
        for (j = 0; j <= N; j++)
            dist2[i][j] = BIG;
    i = s.row; j = s.col;
    dist2[i][j] = 0;
    que.push(s);
    while (!que.empty()) {
        cur = que.front(); que.pop();
        i = cur.row; j = cur.col;
        if (dist2[i][j] > T) continue;
        if (maze1[i][j] == 'Y') continue;
        if (store[i][j].on) {
            if (dist2[i][j] <= T && dist2[i][j] <= dist1[i][j]) {
                for (k = 1; k <= store[i][j].size; k++)
                    edges[s.tag].push_back(store[i][j].list[k]);
            }
        }
        if (dist2[i][j] >= dist1[i][j]) continue;
        // four directions
        if (i - 1 >= 0 && dist2[i - 1][j] > dist2[i][j] + 1) {
            dist2[i - 1][j] = dist2[i][j] + 1;
            nxt.row = i - 1; nxt.col = j;
            que.push(nxt);
        }
        if (i + 1 < N && dist2[i + 1][j] > dist2[i][j] + 1) {
            dist2[i + 1][j] = dist2[i][j] + 1;
            nxt.row = i + 1; nxt.col = j;
            que.push(nxt);
        }
        if (j - 1 >= 0 && dist2[i][j - 1] > dist2[i][j] + 1) {
            dist2[i][j - 1] = dist2[i][j] + 1;
            nxt.row = i; nxt.col = j - 1;
            que.push(nxt);
        }
        if (j + 1 < N && dist2[i][j + 1] > dist2[i][j] + 1) {
            dist2[i][j + 1] = dist2[i][j] + 1;
            nxt.row = i; nxt.col = j + 1;
            que.push(nxt);
        }
    }
}

void BFS_A(Coord s) {
    int i, j;
    Coord cur, nxt;
    i = s.row; j = s.col;
    dist1[i][j] = 0;
    que.push(s);
    while (!que.empty()) {
        cur = que.front(); que.pop();
        i = cur.row; j = cur.col;
        if (maze1[i][j] == 'Y') continue;
        if (i - 1 >= 0 && dist1[i - 1][j] > dist1[i][j] + 1) {
            dist1[i - 1][j] = dist1[i][j] + 1;
            nxt.row = i - 1; nxt.col = j;
            que.push(nxt);
        }
        if (i + 1 < N && dist1[i + 1][j] > dist1[i][j] + 1) {
            dist1[i + 1][j] = dist1[i][j] + 1;
            nxt.row = i + 1; nxt.col = j;
            que.push(nxt);
        }
        if (j - 1 >= 0 && dist1[i][j - 1] > dist1[i][j] + 1) {
            dist1[i][j - 1] = dist1[i][j] + 1;
            nxt.row = i; nxt.col = j - 1;
            que.push(nxt);
        }
        if (j + 1 < N && dist1[i][j + 1] > dist1[i][j] + 1) {
            dist1[i][j + 1] = dist1[i][j] + 1;
            nxt.row = i; nxt.col = j + 1;
            que.push(nxt);
        }
    }
}
